const cb = $json.callback_data;
if (cb === "cat_ver_todas") {
  return [{
    json: {
      mensaje: "🛒 *Categorías*\n\nSelecciona una categoría:",
      reply_markup: {
        inline_keyboard: [
          [{ text: "☕ Bebidas", callback_data: "cat_bebidas" }],
          [{ text: "🍔 Comidas", callback_data: "cat_comidas" }],
          [{ text: "⬅️ Volver", callback_data: "back_menu" }]
        ]
      },
      session_updates: {
        estado_fsm: "SELECCION_CANTIDAD",
        carrito_json: $json.carrito_json || "[]",
        contexto_json: $json.contexto_json || "{}"
      }
    }
  }];
} else if (cb === "confirm_track") {
  return [{
    json: {
      mensaje: "📍 *Seguimiento*\n\nPor favor, ingresa tu número de orden (ej: ORD-1234):",
      reply_markup: {},
      session_updates: {
        estado_fsm: "TRACK_ORDER",
        carrito_json: $json.carrito_json || "[]",
        contexto_json: $json.contexto_json || "{}"
      }
    }
  }];
} else if (cb === "cart_ver_historial") {
  return [{
    json: {
      mensaje: "📋 *Historial de Pedidos*\n\nNo tienes pedidos recientes.",
      reply_markup: {
        inline_keyboard: [[{ text: "⬅️ Volver", callback_data: "back_menu" }]]
      },
      session_updates: {
        estado_fsm: "MENU_PRINCIPAL",
        carrito_json: $json.carrito_json || "[]",
        contexto_json: $json.contexto_json || "{}"
      }
    }
  }];
}

// Default (no callback or back_menu)
return [{
  json: {
    mensaje: "¡Bienvenido a DeliveryBot! 🍔\n\nPor favor, selecciona una opción:",
    reply_markup: {
      inline_keyboard: [
        [
          { text: "🛒 Hacer Pedido", callback_data: "cat_ver_todas" }
        ],
        [
          { text: "📋 Mis Pedidos", callback_data: "cart_ver_historial" },
          { text: "📍 Seguir Pedido", callback_data: "confirm_track" }
        ]
      ]
    },
    session_updates: {
      estado_fsm: "MENU_PRINCIPAL",
      carrito_json: $json.carrito_json || "[]",
      contexto_json: $json.contexto_json || "{}"
    }
  }
}];
